// The engine under the three Circle Carousels: covers ride a conveyor along a path, and their size is a function of
// where on the path they are, so each cover grows as it travels. The conveyor is one number, `shift`, eased over the
// clip; each cover is placed from (its index / count + shift) mod 1. Bigger covers draw over smaller ones.

import React from 'react';
import { Layer, dropShadow } from '@kinetographdev/core';
import { Photo, easeOut, pick, prog } from './kit.js';

export interface Placement {
  x: number;
  y: number;
  /** degrees */
  rot: number;
  /** side of the square, in px; 0 hides the cover */
  size: number;
}

export interface ChainProps {
  frame: number;
  images: string[];
  count: number;
  /** conveyor position in turns at this frame */
  shift: number;
  place: (u: number, i: number) => Placement;
  /** px radius of the corner */
  radius: number;
  /** frames between one cover starting its entrance and the next */
  stagger: number;
  /** shadow strength, 0 for none */
  shadow: number;
  idPrefix: string;
}

export const Chain = ({ frame, images, count, shift, place, radius, stagger, shadow, idPrefix }: ChainProps) => {
  const items = Array.from({ length: count }, (_, i) => {
    const u = (((i / count + shift) % 1) + 1) % 1;
    const p = place(u, i);
    // entrance: each cover grows from nothing in turn, round the ring, so the ring is drawn in by a sweep
    const enter = prog(frame, 2 + i * stagger, 2 + i * stagger + 22, easeOut);
    return { i, p, enter, size: p.size * enter };
  }).filter((it) => it.size > 0.4);
  items.sort((a, b) => a.size - b.size || a.i - b.i);
  return (
    <Layer id={`${idPrefix}-chain`}>
      {items.map(({ i, p, size }) => (
        <Layer
          key={i}
          id={`${idPrefix}-c${i}`}
          x={p.x}
          y={p.y}
          rotation={p.rot}
          effects={shadow > 0 ? [dropShadow({ x: 0, y: size * 0.05, blur: size * 0.12, color: `rgba(20,20,30,${0.22 * shadow})` })] : undefined}
        >
          <Photo file={pick(images, i)} w={size} h={size} radius={Math.min(radius, size * 0.1)} />
        </Layer>
      ))}
    </Layer>
  );
};

// Circle Carousel 2: a spiral. The covers wind inward from a wide, tiny start to one large cover in the middle, and the
// whole spiral turns, so each cover is carried in, grows, and is swallowed at the centre as the next one is born at the
// rim. The spiral is tilted a little and drifts in a slow rotation; the ground is a cool grey.
// The camera rides the front of the sweep inward along the spiral (zoomed out as the covers grow), pulls out past the
// mark to show the whole spiral, holds while it winds, then pushes into the largest cover. Motion blur on fast moves.

import React from 'react';
import { z } from 'zod';
import { useCurrentFrame } from 'remotion';
import { Layer } from '@kinetographdev/core';
import { Chain } from './chain.js';
import { chainCamera, Rig, shutterOf, DEFAULT_PHOTOS, Ground, H, Label, W, easeCam, ease, hex, imagesSchema, lerp, prog, ramp, smooth, useFont } from './kit.js';

export const circleCarousel2Schema = z.object({
  images: imagesSchema,
  count: z.number().int().min(8).max(60).describe('How many covers ride the spiral.'),
  outerRadius: z.number().min(200).max(700).describe('Radius of the rim, where the covers are born, in px.'),
  innerRadius: z.number().min(0).max(300).describe('Radius at the end of the spiral, where the largest cover sits, in px.'),
  windings: z.number().min(0.5).max(3).describe('How many times the spiral winds round on its way in.'),
  minSize: z.number().min(2).max(60).describe('Side of the smallest cover, in px.'),
  maxSize: z.number().min(80).max(420).describe('Side of the largest cover, in px.'),
  growth: z.number().min(0.6).max(4).describe('How late the covers grow; higher keeps them small until near the centre.'),
  travel: z.number().min(0.05).max(1.5).describe('How far the covers travel along the spiral over the shot, as a fraction of its length.'),
  travelStart: z.number().int().min(0).describe('Frame the covers start moving.'),
  travelFrames: z.number().int().min(10).describe('Frames the travel takes, eased in and out.'),
  swirl: z.number().min(-60).max(60).describe('Degrees the whole spiral turns over the shot, on top of the covers travelling along it.'),
  tilt: z.number().min(0).max(40).describe('Degrees each cover leans along the spiral.'),
  stagger: z.number().min(0).max(4).describe('Frames between one cover appearing and the next.'),
  rideZoom: z.number().min(1).max(5).describe('Zoom of the opening shot on the smallest covers.'),
  push: z.number().min(0).max(1).describe('How far the camera pushes into the largest cover at the end.'),
  motionBlur: z.number().min(0).max(1).describe('Camera motion blur shutter in frames, used while the camera moves fast. 0 turns it off.'),
  title: z.string().describe('Small title at the bottom right. Empty for none.'),
  caption: z.string().describe('Smaller line under the title. Empty for none.'),
  font: z.string().describe('Google Fonts family for the label.'),
  colors: z.object({ ground: hex.describe('Background.'), ink: hex.describe('Title.'), muted: hex.describe('Caption.') }).describe('Colours.'),
});
export type CircleCarousel2Props = z.infer<typeof circleCarousel2Schema>;

export const circleCarousel2Defaults: CircleCarousel2Props = {
  images: DEFAULT_PHOTOS.slice(8).concat(DEFAULT_PHOTOS.slice(0, 8)),
  count: 38,
  outerRadius: 470,
  innerRadius: 90,
  windings: 1.15,
  minSize: 5,
  maxSize: 270,
  growth: 2.0,
  travel: 0.4,
  travelStart: 128,
  travelFrames: 100,
  swirl: 14,
  tilt: 6,
  stagger: 2.6,
  rideZoom: 2.2,
  push: 0.35,
  motionBlur: 0,
  title: 'Circle Carousel 2',
  caption: 'A spiral, wound inward',
  font: 'Inter',
  colors: { ground: '#e9ecf0', ink: '#14171c', muted: '#7a828d' },
};

export const CIRCLE2_DURATION = 275;

export const CircleCarousel2 = (p: CircleCarousel2Props) => {
  const f = useCurrentFrame();
  const font = useFont(p.font);
  const shiftAt = (t: number) => p.travel * prog(t, p.travelStart, p.travelStart + p.travelFrames, ease);
  const shift = shiftAt(f);
  const turnAt = (t: number) => p.swirl * prog(t, 0, CIRCLE2_DURATION - 1, easeCam);
  const where = (u: number) => {
    // radius shrinks with an ease so the covers bunch toward the centre
    const r = lerp(p.outerRadius, p.innerRadius, Math.pow(u, 0.8));
    const a = (-90 + u * p.windings * 360) * (Math.PI / 180);
    // size: grows over the whole path, then folds to nothing in the last stretch (swallowed)
    const rise = Math.pow(u / 0.9, p.growth);
    const size = u <= 0.9 ? lerp(p.minSize, p.maxSize, rise) : lerp(p.minSize, p.maxSize, smooth((1 - u) / 0.1));
    return { x: Math.cos(a) * r, y: Math.sin(a) * r, size };
  };
  const place = (u: number) => {
    const w = where(u);
    return { x: w.x, y: w.y, rot: p.tilt * Math.sin(u * 6.28), size: w.size };
  };
  const sweepEnd = 4 + p.count * p.stagger + 10;
  const pullA = sweepEnd - 8;
  const pushA = p.travelStart + p.travelFrames + 4;
  const base = chainCamera({
    count: p.count, stagger: p.stagger, where, shiftAt, rest: { cx: 0, cy: 20, zoom: 0.98 }, rideZoom: p.rideZoom, push: p.push,
    pullA, pullB: pullA + 34, pushA, pushB: pushA + 34, roll: [4, -3],
  });
  // the world turns with the swirl, so the camera's point turns with it
  const camAt = (t: number) => {
    const c = base(t);
    const th = (turnAt(t) * Math.PI) / 180;
    return { ...c, cx: c.cx * Math.cos(th) - c.cy * Math.sin(th), cy: c.cx * Math.sin(th) + c.cy * Math.cos(th) };
  };
  const c = camAt(f);
  const shutter = p.motionBlur > 0 ? shutterOf(camAt, f, 420, 14, p.motionBlur) : 0;
  return (
    <Layer id="root">
      <Ground color={p.colors.ground} />
      <Rig cx={c.cx} cy={c.cy} zoom={c.zoom} roll={c.roll} shutter={shutter}>
        <Layer id="world" rotation={turnAt(f)}>
          <Chain frame={f} images={p.images} count={p.count} shift={shift} idPrefix="cc2" radius={2} stagger={p.stagger} shadow={1} place={place} />
        </Layer>
      </Rig>
      <Label x={W - 72} y={H - 130} title={p.title} sub={p.caption} font={font} ink={p.colors.ink} muted={p.colors.muted} opacity={ramp(f, pullA + 30, pullA + 60, 0, 1)} align="right" />
    </Layer>
  );
};

// Shared by the carousel components: easing, key frames, the default photo set, a photo card and font loading.
// Every function is a pure function of the frame number.

import React from 'react';
import { z } from 'zod';
import { Easing, interpolate, staticFile } from 'remotion';
import { Image, Layer, Rect, Text } from '@kinetographdev/core';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';

export const W = 1920;
export const H = 1080;

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
/** slow in, slow out */
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
/** fast start, long settle: a flick that dies away */
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
/** gentle start, then speed */
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);
/** a soft in and out for camera moves */
export const easeCam = Easing.bezier(0.5, 0, 0.1, 1);

/** from `a` at frame f0 to `b` at frame f1, held outside, with an easing */
export const ramp = (f: number, f0: number, f1: number, a: number, b: number, e: (t: number) => number = ease) =>
  interpolate(f, [f0, f1], [a, b], { ...clamp, easing: e });

/** 0 to 1 over [f0, f1] with an easing */
export const prog = (f: number, f0: number, f1: number, e: (t: number) => number = ease) => ramp(f, f0, f1, 0, 1, e);

/** Piecewise through [frame, value] keys, one easing per segment. */
export function keys(f: number, k: [number, number][], e: (t: number) => number = ease): number {
  if (f <= k[0][0]) return k[0][1];
  for (let i = 1; i < k.length; i++) {
    if (f <= k[i][0]) {
      const [a, va] = k[i - 1];
      const [b, vb] = k[i];
      return va + (vb - va) * e((f - a) / (b - a));
    }
  }
  return k[k.length - 1][1];
}

export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
export const smooth = (t: number) => {
  const c = Math.min(1, Math.max(0, t));
  return c * c * (3 - 2 * c);
};

export const hex = z.string().describe('A CSS colour.');

/** The photo set the components default to: public-domain NASA pictures, see photos/CREDITS.md. */
export const DEFAULT_PHOTOS = [
  'nasa-earth-2', 'nasa-nebula-1', 'nasa-mars-1', 'nasa-moon-1', 'nasa-saturn-1',
  'nasa-storm-1', 'nasa-desert-1', 'nasa-galaxy-1', 'nasa-glacier-1', 'nasa-city-1', 'nasa-jupiter-1',
  'nasa-reef-1', 'nasa-iss-1', 'nasa-clouds-1', 'nasa-nebula-2', 'nasa-aurora-2',
  'nasa-mountains-1', 'nasa-telescope-1', 'nasa-sun-1', 'nasa-river-1', 'nasa-galaxy-2', 'nasa-moon-2', 'nasa-storm-2'
].map((n) => `photos/${n}.jpg`);

export const imagesSchema = z
  .array(z.string())
  .min(1)
  .describe('Pictures, as paths under public/ (or full URLs). They repeat when there are fewer than the count.');

/** A path under public/ or a URL, as an image source. */
export const src = (s: string) => (/^(https?:|data:|\/)/.test(s) ? s : staticFile(s));

/** Loads a Google font and returns the family name that is registered. */
export const useFont = (family: string, weights: string[] = ['400', '500']): string =>
  makeGoogleFont(family).loadFont('normal', { weights }).fontFamily;

export const useFontItalic = (family: string, weights: string[] = ['400']): string =>
  makeGoogleFont(family).loadFont('italic', { weights }).fontFamily;

/** A picture cropped to a rounded card of w x h, centred on the layer's origin. */
export const Photo = ({ file, w, h, radius = 0, opacity, id, reveal = 1 }: { file: string; w: number; h: number; radius?: number; opacity?: number; id?: string; reveal?: number }) => (
  <Image
    id={id}
    src={src(file)}
    x={-w / 2}
    y={-h / 2}
    width={w}
    height={h}
    fit="cover"
    opacity={opacity}
    clip={radius > 0 || reveal < 1 ? { kind: 'inset', radius, bottom: (1 - reveal) * h } : undefined}
  />
);

/** A flat ground. */
export const Ground = ({ color }: { color: string }) => <Rect id="ground" width={W} height={H} fill={color} />;

export const pick = <T,>(list: T[], i: number): T => list[((i % list.length) + list.length) % list.length];

export { Layer };

/** A quiet two-line label: a title and a smaller line under it. */
export const Label = ({ x, y, title, sub, font, ink, muted, opacity = 1, align = 'left' }: { x: number; y: number; title: string; sub: string; font: string; ink: string; muted: string; opacity?: number; align?: 'left' | 'right' }) => {
  const maxWidth = 700;
  const ox = align === 'right' ? -maxWidth : 0;
  return (
    <Layer id="label" x={x} y={y} opacity={opacity}>
      {title ? <Text id="label-title" font={font} weight={500} size={30} color={ink} x={ox} y={0} maxWidth={maxWidth} align={align}>{title}</Text> : null}
      {sub ? <Text id="label-sub" font={font} weight={400} size={21} color={muted} x={ox} y={title ? 44 : 0} maxWidth={maxWidth} align={align}>{sub}</Text> : null}
    </Layer>
  );
};

/** "nasa-earth-2" in photos/nasa-earth-2.jpg becomes "Earth". Used for default card labels. */
export const nameOf = (file: string) => {
  const m = /nasa-([a-z]+)-/.exec(file);
  return m ? m[1][0].toUpperCase() + m[1].slice(1) : '';
};

/**
 * A 2D camera: the world point (cx, cy) sits at the middle of the frame, `zoom` scales about it and `roll` turns the
 * frame (degrees, clockwise). `shutter` is the motion blur in frames (0 for none).
 */
export const Rig = ({ cx, cy, zoom, roll = 0, shutter = 0, children }: { cx: number; cy: number; zoom: number; roll?: number; shutter?: number; children: React.ReactNode }) => (
  <Layer id="rig" motionBlur={shutter > 0 ? { samples: 20, shutter } : undefined}>
    <Layer id="rig-eye" x={W / 2} y={H / 2} scale={zoom} rotation={roll}>
      <Layer id="rig-world" x={-cx} y={-cy}>
        {children}
      </Layer>
    </Layer>
  </Layer>
);

/** Motion blur shutter from how far a 2D camera moves between two moments: 0 while it is slow. */
export const shutterOf = (camAt: (f: number) => { cx: number; cy: number; zoom: number; roll?: number }, f: number, span = 400, threshold = 7, shutter = 0.5) => {
  const a = camAt(f - 0.5);
  const b = camAt(f + 0.5);
  const d = Math.hypot((b.cx - a.cx) * b.zoom, (b.cy - a.cy) * b.zoom) + Math.abs(Math.log(b.zoom / a.zoom)) * span + Math.abs((b.roll ?? 0) - (a.roll ?? 0)) * 8;
  return d > threshold ? shutter : 0;
};

export interface ChainCam {
  count: number;
  stagger: number;
  /** Where the cover at position u sits and how big it is, in world px. */
  where: (u: number) => { x: number; y: number; size: number };
  /** Conveyor position at frame t, in turns. */
  shiftAt: (t: number) => number;
  /** The world point shown at the middle of the frame in the ring shot, and its zoom. */
  rest: { cx: number; cy: number; zoom: number };
  rideZoom: number;
  push: number;
  /** Frames: pull out starts and lands, push starts and lands. */
  pullA: number;
  pullB: number;
  pushA: number;
  pushB: number;
  /** Roll in degrees at the start, the end of the ride and at rest. */
  roll: [number, number];
}

/**
 * The camera of a conveyor of covers: it rides the front of the entrance sweep (the cover being born), zoomed so the
 * covers it follows stay about 190 px across, pulls out past the mark and back to the ring shot, holds, then pushes
 * into the biggest cover once the conveyor has stopped.
 */
export const chainCamera = (o: ChainCam) => {
  let hero = o.where(0);
  const endShift = o.shiftAt(1e6);
  for (let i = 0; i < o.count; i += 1) {
    const w = o.where((((i / o.count + endShift) % 1) + 1) % 1);
    if (i === 0 || w.size > hero.size - 0.001) hero = w;
  }
  const io = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
  return (t: number) => {
    const front = Math.min(o.count - 1, Math.max(0, (t - 5) / o.stagger));
    const fw = o.where((((front / o.count + o.shiftAt(t)) % 1) + 1) % 1);
    const zRide = Math.min(o.rideZoom, Math.max(o.rest.zoom, 190 / Math.max(fw.size, 24)));
    const kRing = prog(t, o.pullA, o.pullB, io);
    const over = 1 + 0.045 * Math.sin(prog(t, o.pullB - 4, o.pullB + 26, (x: number) => x) * Math.PI);
    let cx = lerp(fw.x, o.rest.cx, kRing);
    let cy = lerp(fw.y, o.rest.cy, kRing);
    let zoom = lerp(zRide, o.rest.zoom, kRing) * (kRing >= 1 ? over : 1);
    const kPush = prog(t, o.pushA, o.pushB, (x: number) => 1 - Math.pow(1 - x, 3));
    // re-centre on the hero only as far as the push goes in: with no push the ring stays framed whole
    const aim = Math.min(1, o.push * 3);
    cx = lerp(cx, lerp(cx, hero.x, aim), kPush);
    cy = lerp(cy, lerp(cy, hero.y, aim), kPush);
    zoom = lerp(zoom, o.rest.zoom * (1 + o.push), kPush);
    const roll = keys(t, [[0, o.roll[0]], [o.pullA, o.roll[1]], [o.pullB + 24, 0], [o.pushB, 0]]);
    return { cx, cy, zoom, roll };
  };
};
